async function setupForm({doc, call, createToast, router}) {
    const actions = []

    if(doc.status == "Proposal/Quotation"){
        // if Quotation is created then Show Go to Quotation Buttton
        const result = await call('frappe.client.get_value', {
            doctype: 'Quotation',
            filters: { custom_deal: doc.name },
            fieldname: 'name'
        })
        const quotation = result?.name
        if (quotation) {
            actions.push({
                "label": "Go to Quotation",
                "onClick": () => {
                    window.open(`/app/quotation/${quotation}`, '_blank')
                }
            })
        }else{
            actions.push({
                "label": "Create Quotation",
                "onClick": async() => {

                    let creation = await call('fcrm_connector.custom_script.deal.create_quotation', {
                        doctype: 'CRM Deal',
                        name: doc.name
                    })

                    if(creation.success){
                        await createToast({
                          title: __('Created Quotation successfully'),
                          icon: 'check',
                          iconClasses: 'text-green-600',
                        })


                    }else{
                         await createToast({
                            title: __('Error Creating Quotation'),
                            text: __(creation.err),
                            icon: 'x',
                            iconClasses: 'text-red-600',
                          })
                    }
                }
            })
        }
    }

    return {
        actions,
    }
}
